// spec: specs/chat-conversations.md (3.1–3.3) · кейсы: .qa/tests/chat-conversations/CHAT-OPEN-05, -06, -07.md
// seed: tests/seed.chat.spec.ts · прод, только чтение: запись заблокирована, SW выключен; уведомления не нажимать.
// Только Android (Pixel 7, Chromium): на iPhone/WebKit route не перехватывает запросы через service worker (27.10 ушли PATCH под chat).
import { test } from '@playwright/test';
import { blockWrites, expectListFirstOnMobile, headerBell, headerBurger, headerChatIcon, LOAD } from './open-conversation.helpers';

test.use({ storageState: '../auth/chat.json', serviceWorkers: 'block' });

const LISTING = '/businessdetail?id=5832e079-87c7-49a8-9c24-97e7664dcba6';
const START_PAGES = [
  { name: 'главная', url: '/home' },
  { name: 'объявление', url: LISTING },
];

test.describe('Чат / переписки — вход в /messages на мобайле', () => {
  for (const start of START_PAGES) {
    test(`Мобайл: иконка чата в шапке (${start.name}) → список переписок в первом экране, меню ниже #c5ed06 @android @prod-safe`, async ({ page }) => {
      await blockWrites(page);
      await page.goto(start.url);
      await headerChatIcon(page).click(LOAD);
      await expectListFirstOnMobile(page);
    });

    test(`Мобайл: колокольчик → «הודעות» (${start.name}) → список переписок в первом экране, меню ниже #c5ed06 @android @prod-safe`, async ({ page }) => {
      await blockWrites(page);
      await page.goto(start.url);
      await headerBell(page).click(LOAD);
      // Ссылка «הודעות» внизу окна колокольчика; сами уведомления не нажимать (это запись is_read).
      await page.getByRole('dialog').getByRole('link', { name: 'הודעות', exact: true }).click(LOAD);
      await expectListFirstOnMobile(page);
    });
  }

  test('Мобайл: гамбургер → «הודעות» → список переписок в первом экране, меню ниже #c5ed06 @android @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto('/home');
    await headerBurger(page).click(LOAD);
    await page.getByRole('dialog').getByRole('link', { name: 'הודעות' }).click();
    await expectListFirstOnMobile(page);
  });

  test('Мобайл: прямая загрузка /messages → список переписок в первом экране, меню ниже #c5ed06 @android @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto('/messages');
    await expectListFirstOnMobile(page);
  });
});
